import {voices,opinionSource} from './opinions-data.js';
import {opinionPositions,opinionWindowPosition} from './opinion-layout.js';
const escape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class OpinionOrbit{
 constructor({stage,context,getPaused,getObstacles,announce,onSelect}){
  Object.assign(this,{stage,context,getPaused,getObstacles,announce,onSelect});this.active=false;this.phase=.6;this.selected=null;this.hovered=false;this.focused=false;this.lastTime=0;
  this.layer=document.createElement('div');this.layer.className='opinion-orbit';this.layer.hidden=true;this.layer.setAttribute('role','group');this.layer.setAttribute('aria-label','Opiniones por postura alrededor del títere');stage.append(this.layer);
  this.guide=document.createElement('section');this.guide.className='opinion-guide';this.guide.id='opinion-guide';this.guide.hidden=true;this.guide.innerHTML='<p class="opinion-eyebrow">LAS OPINIONES · CUATRO POSTURAS</p><h2><span class="sr-only">Una decisión. Cuatro formas de vivirla.</span><img src="./assets/headings/opinion-guide.svg" alt="" aria-hidden="true"></h2><p>Las voces también recorren este cuerpo. Elige una partícula para escuchar lo que cada persona imagina, siente y necesita.</p><p class="opinion-guide-note">Cada color guarda una postura. Puedes seguir girando el títere.</p><button type="button" class="opinion-back">← Volver a explorar el cuerpo</button>';context.prepend(this.guide);this.guide.querySelector('button').onclick=()=>{this.setActive(false);document.querySelector('#body-canvas').focus({preventScroll:true});};
  this.panel=document.createElement('section');this.panel.id='opinion-window';this.panel.className='opinion-window';this.panel.hidden=true;this.panel.tabIndex=-1;this.panel.setAttribute('role','region');this.panel.setAttribute('aria-labelledby','opinion-title');context.append(this.panel);
  this.buttons=voices.map((v,i)=>{const b=document.createElement('button');b.type='button';b.className='opinion-particle';b.style.setProperty('--voice-color',v.color);b.setAttribute('aria-label',`${String(i+1).padStart(2,'0')} · ${v.stance}. ${v.name}, ${v.age} años. Leer opiniones`);b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls','opinion-window');b.innerHTML=`<span class="opinion-spark" aria-hidden="true"></span><span class="opinion-particle-copy"><small>${String(i+1).padStart(2,'0')} · ${v.short}</small><span>${v.name}</span></span>`;b.onclick=()=>this.open(i);b.onpointerenter=()=>this.hovered=true;b.onpointerleave=()=>this.hovered=false;this.layer.append(b);return b;});
  this.layer.addEventListener('focusin',()=>this.focused=true);this.layer.addEventListener('focusout',e=>{if(!this.layer.contains(e.relatedTarget))this.focused=false;});
  this.panel.addEventListener('click',e=>{if(e.target.closest('[data-opinion-close]'))this.closeWindow();const step=e.target.closest('[data-topic-step]');if(step){const count=voices[this.selected].topics.length;this.topic=(this.topic+Number(step.dataset.topicStep)+count)%count;this.renderTopic();this.panel.querySelector(`[data-topic-step="${step.dataset.topicStep}"]`).focus({preventScroll:true});}});
  this.panel.addEventListener('change',e=>{if(e.target.matches('#opinion-topic')){this.topic=Number(e.target.value);this.renderTopic();}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!this.panel.hidden){e.preventDefault();this.closeWindow();}});
  this.observer=new ResizeObserver(()=>{if(this.active){this.position();this.positionWindow();}});this.observer.observe(stage);
  window.addEventListener('resize',()=>this.active&&this.positionWindow());
 }
 setActive(active){cancelAnimationFrame(this.animationId);this.active=active;this.closeWindow(false);this.layer.hidden=!active;this.guide.hidden=!active;document.body.classList.toggle('opinions-active',active);document.querySelector('#nav-voices').setAttribute('aria-pressed',String(active));this.hovered=false;this.focused=false;this.lastTime=0;if(active){this.position();this.announce('Cuatro opiniones disponibles alrededor del títere. Elige una partícula por postura.');this.animationId=requestAnimationFrame(t=>this.tick(t));}else this.announce('Puedes continuar explorando las zonas del cuerpo.');}
 tick(ms){if(!this.active)return;const dt=this.lastTime?Math.min((ms-this.lastTime)/1000,.05):0;this.lastTime=ms;if(!document.hidden&&!this.getPaused()&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!this.hovered&&!this.focused&&this.panel.hidden)this.phase+=dt*Math.PI*2/58;if(!this.hovered&&!this.focused&&this.panel.hidden&&!this.getPaused())this.position();this.animationId=requestAnimationFrame(t=>this.tick(t));}
 position(){const points=opinionPositions({width:this.stage.clientWidth,height:this.stage.clientHeight,phase:this.phase,obstacles:this.getObstacles()});this.orbitPoints=points;this.buttons.forEach((b,i)=>{const p=points[i];b.style.left=`${p.x-p.width/2}px`;b.style.top=`${p.y-p.height/2}px`;b.style.width=`${p.width}px`;b.style.height=`${p.height}px`;});}
 soundMotion(){const p=this.orbitPoints?.[0],width=this.stage.clientWidth||1;return {active:this.active,moving:this.active&&!document.hidden&&!this.getPaused()&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!this.hovered&&!this.focused&&this.panel.hidden,phase:this.phase,pan:p?(p.x/width-.5)*1.4:0};}
 open(index){this.selected=index;this.topic=Math.max(0,voices[index].topics.findIndex(([label])=>label==='Cuerpo'));this.buttons.forEach((b,i)=>b.setAttribute('aria-expanded',String(i===index)));const v=voices[index];this.panel.style.setProperty('--voice-color',v.color);this.panel.innerHTML=`<div class="opinion-window-top"><span>${String(index+1).padStart(2,'0')} · LAS OPINIONES</span><button data-opinion-close type="button" aria-label="Cerrar opinión">×</button></div><h2 id="opinion-title"><span class="sr-only">${escape(v.stance)}</span><img src="./assets/headings/opinion-${v.id}.svg" alt="" aria-hidden="true"></h2><p class="opinion-author">${v.name}, ${v.age} años</p><blockquote class="opinion-principal">“${escape(v.text)}”</blockquote><div class="opinion-topic-controls"><label for="opinion-topic">Explora un tema</label><select id="opinion-topic" aria-label="Tema de la opinión de ${v.name}">${v.topics.map(([label],i)=>`<option value="${i}">${escape(label)}</option>`).join('')}</select></div><div class="opinion-topic" aria-live="polite"></div><p class="opinion-source">${v.adapted?'Frase adaptada de entrevista':'Fragmento de entrevista'} · texto proporcionado para la experiencia.</p>`;this.panel.hidden=false;this.renderTopic();this.positionWindow();this.panel.focus({preventScroll:true});if(innerWidth<=1050)this.panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});this.onSelect(index);this.announce(`${v.stance}. ${opinionSource(v)}.`);}
 renderTopic(){const v=voices[this.selected],[label,text]=v.topics[this.topic];this.panel.querySelector('#opinion-topic').value=String(this.topic);this.panel.querySelector('.opinion-topic').innerHTML=`<p class="opinion-topic-label">${escape(label)}</p><blockquote>“${escape(text)}”</blockquote><div class="opinion-topic-pagination"><button data-topic-step="-1" type="button" aria-label="Tema anterior">←</button><span>${this.topic+1} / ${v.topics.length} temas</span><button data-topic-step="1" type="button" aria-label="Tema siguiente">→</button></div>`;this.positionWindow();}
 positionWindow(){if(this.panel.hidden)return;if(innerWidth<=1050){this.panel.style.removeProperty('left');this.panel.style.removeProperty('top');this.panel.style.removeProperty('width');return;}const point=this.buttons[this.selected].getBoundingClientRect(),rect=this.context.getBoundingClientRect(),panelWidth=Math.min(360,rect.width-12);this.panel.style.width=`${panelWidth}px`;const p=opinionWindowPosition({viewportWidth:innerWidth,viewportHeight:innerHeight,panelWidth,panelHeight:this.panel.offsetHeight,preferredLeft:rect.left+8,particleTop:point.top,verticalLift:this.selected===0||this.selected===1?72:0});Object.assign(this.panel.style,{left:`${p.left}px`,top:`${p.top}px`,width:`${p.width}px`});}
 closeWindow(restore=true){const wasOpen=!this.panel.hidden;this.panel.hidden=true;this.buttons.forEach(b=>b.setAttribute('aria-expanded','false'));if(restore&&wasOpen&&this.active&&this.selected!==null)this.buttons[this.selected].focus({preventScroll:true});this.selected=null;}
}
